declare module '@glimmer/opcode-compiler/lib/opcode-builder/helpers/resolution' {
    import type { BlockMetadata, ClassicResolver, Expressions, Nullable, ProgramConstants, ResolveComponentOp, ResolveComponentOrHelperOp, ResolveHelperOp, ResolveModifierOp, ResolveOptionalComponentOrHelperOp } from "@glimmer/interfaces";
    export const isGetFreeComponent: (opcode: Expressions.Expression) => opcode is Expressions.GetFree | Expressions.GetLexicalSymbol;
    export const isGetFreeModifier: (opcode: Expressions.Expression) => opcode is Expressions.GetFree | Expressions.GetLexicalSymbol;
    export const isGetFreeHelper: (opcode: Expressions.Expression) => opcode is Expressions.GetFree | Expressions.GetLexicalSymbol;
    export const isGetFreeComponentOrHelper: (opcode: Expressions.Expression) => opcode is Expressions.GetFree | Expressions.GetLexicalSymbol;
    /**
     * <Foo/>
     * <Foo></Foo>
     * <Foo @arg={{true}} />
     */
    export function resolveComponent(
     resolver: Nullable<ClassicResolver>,
     constants: ProgramConstants,
     meta: BlockMetadata,
     [, expr, then]: ResolveComponentOp
    ): void;
    /**
     * (helper)
     * (helper arg)
     */
    export function resolveHelper(
     resolver: Nullable<ClassicResolver>,
     constants: ProgramConstants,
     meta: BlockMetadata,
     [, expr, then]: ResolveHelperOp
    ): void;
    /**
     * <div {{modifier}}/>
     * <div {{modifier arg}}/>
     * <Foo {{modifier}}/>
     */
    export function resolveModifier(
     resolver: Nullable<ClassicResolver>,
     constants: ProgramConstants,
     meta: BlockMetadata,
     [, expr, then]: ResolveModifierOp
    ): void;
    /**
     * {{component-or-helper arg}}
     */
    export function resolveComponentOrHelper(
     resolver: Nullable<ClassicResolver>,
     constants: ProgramConstants,
     meta: BlockMetadata,
     [, expr, { ifComponent, ifHelper }]: ResolveComponentOrHelperOp
    ): void;
    /**
     * {{maybeHelperOrComponent}}
     */
    export function resolveOptionalComponentOrHelper(
     resolver: Nullable<ClassicResolver>,
     constants: ProgramConstants,
     meta: BlockMetadata,
     [, expr, { ifComponent, ifHelper, ifValue }]: ResolveOptionalComponentOrHelperOp
    ): void;
}